#include <iostream>

class Account {
private:
    int m_balance{ 0 };

public:
    void deposit(int amount) {
        m_balance += amount;
    }

    void withdraw(int amount) {
        if (amount <= m_balance) {
            m_balance -= amount;
        }
    }

    int getBalance() const {
        return m_balance;
    }
};

int main() {
    int n;
    std::cin >> n;
    Account a;
    for (int i = 0; i < n; ++i) {
        char op;
        int amount;
        std::cin >> op >> amount;
        if (op == 'D') {
            a.deposit(amount);
        } else {
            a.withdraw(amount);
        }
        std::cout << "Balance: " << a.getBalance() << "\n";
    }
    std::cout << "Final: " << a.getBalance() << "\n";
    return 0;
}
